function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

// Line-by-line parser — handles Google Docs plain text single-newline format
function parseDoc(raw){
  var lines = raw.replace(/\r/g,'').split('\n');
  var sections = [];
  var cur = null;
  for(var i=0;i<lines.length;i++){
    var line = lines[i];
    var t = line.trim();
    if(!t) continue;
    var prevBlank = i===0 || !lines[i-1].trim();
    var isBullet = /^[•*\-]/.test(t);
    var isShort = t.length < 90;
    var noEndPunct = !/[.!?]$/.test(t);
    var isTitle = !isBullet && prevBlank && isShort && noEndPunct;
    if(isTitle){
      if(cur) sections.push(cur);
      cur = {title:t, items:[]};
    } else if(cur){
      var stripped = t.replace(/^[•*\-]\s*/,'');
      if(stripped){
        var isIndented = /^\s{4,}/.test(line);
        var isAction = /action item|assigned to|pending|urgent|blocked|due:|follow.up|must:/i.test(stripped);
        cur.items.push({text:stripped, sub:isIndented, action:isAction});
      }
    }
  }
  if(cur) sections.push(cur);
  return sections.filter(function(s){ return s.title.length > 1; });
}

function cat(t){
  var l = t.toLowerCase();
  if(/jaguar|lewis|fordham|canvas forum|nett.?sol|jon hart|titan|spears|guac|certitrek|cfg|albert|ground up/.test(l)) return 'cl';
  if(/daria|hesham|jasmin|david smith|devoreaux|agustin|chareze|lorenna|princess|gwen/.test(l)) return 'tm';
  if(/crm copilot|ai website|custom gpt|website change/.test(l)) return 'pr';
  return 'op';
}

