  cl: {label:'Client',  color:'#3b82f6', bg:'rgba(59,130,246,0.12)',  icon:'&#x1F3E2;'},
  tm: {label:'Team',    color:'#a855f7', bg:'rgba(168,85,247,0.12)',  icon:'&#x1F465;'},
  pr: {label:'Product', color:'#10b981', bg:'rgba(16,185,129,0.12)',  icon:'&#x1F916;'},
  op: {label:'Ops',     color:'#f59e0b', bg:'rgba(245,158,11,0.12)',  icon:'&#x2699;'}
};

var sections = parseDoc(rawText);
var d = new Date(info.modifiedTime || info.createdTime || Date.now());
var dateStr = d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
var timeStr = d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZoneName:'short'});
var total   = sections.length;
var actions = sections.reduce(function(n,s){return n+s.items.filter(function(i){return i.action;}).length;},0);
var clients = sections.filter(function(s){return cat(s.title)==='cl';}).length;
var team    = sections.filter(function(s){return cat(s.title)==='tm';}).length;
var product = sections.filter(function(s){return cat(s.title)==='pr';}).length;
var ops     = sections.filter(function(s){return cat(s.title)==='op';}).length;
var docLink = esc(info.webViewLink || '#');

function renderCard(s){
  var c = cat(s.title);
  var m = CAT[c];
  var ac = s.items.filter(function(i){return i.action;}).length;
  var items = s.items.map(function(item){
    var txt = esc(item.text);
    if(/^[A-Z][A-Za-z &()]{2,50}:\s/.test(item.text)){
      txt = txt.replace(/^([^:]{2,55}:\s)/,'<b>$1</b>');
    }
    var cls = 'bi'+(item.sub?' bs':'')+(item.action?' ba':'');
    return '<li class="'+cls+'">'+txt+'</li>';
  }).join('');
  return '<div class="card" data-c="'+c+'" style="--ac:'+m.color+';--ab:'+m.bg+'">' 
    +'<div class="ch" style="border-top:3px solid '+m.color+'">'
      +'<div class="cr"><h3 class="ct">'+esc(s.title)+'</h3>'
      +'<span class="badge" style="background:'+m.bg+';color:'+m.color+'">'+m.icon+' '+m.label+'</span></div>'
      +(ac>0?'<div class="arow"><span class="adot"></span>'+ac+' action item'+(ac!==1?'s':'')+'</div>':'')
    +'</div>'
    +'<div class="cb">'+(items?'<ul class="bl">'+items+'</ul>':'<p class="nc">No details.</p>')+'</div>'
  +'</div>';
}

